/*! `zig` grammar for Highlight.js 11.11.1 — adapted for in-app vendoring.
 * Upstream: highlightjs-zig by lbirkert (https://github.com/lbirkert/highlight.js-zig),
 * grammar author KekOnTheWorld <kekontheworld@gmail.com>; zig has NO official
 * hljs 11.11.1 grammar (absent from the cdnjs/npm language listings), so this
 * third-party grammar is vendored in the SAME self-registering IIFE form as the
 * cdnjs packs below: it registers on the global `hljs` and exports no module.
 * The upstream source is an ES module (src/languages/zig.js) importing its
 * NUMBER mode from src/languages/lib/java.js; this file inlines that mode — the
 * helper vars decimalDigits/frac/hexDigits plus the mode object, renamed NUMBER
 * (a MODE OBJECT, not the hljs core NUMERIC regex) — deletes the import line,
 * and wraps the grammar function in the canonical IIFE wrapper. Grammar body is
 * core-API compatible (plain begin/className/contains), kept verbatim. */
(() => {
  "use strict";

  // --- Inlined from lbirkert/highlight.js-zig src/languages/lib/java.js ---
  // https://docs.oracle.com/javase/specs/jls/se15/html/jls-3.html#jls-3.10
  var decimalDigits = '[0-9](_*[0-9])*';
  var frac = `\\.(${decimalDigits})`;
  var hexDigits = '[0-9a-fA-F](_*[0-9a-fA-F])*';
  var NUMBER = {
    className: 'number',
    variants: [
      // DecimalFloatingPointLiteral
      // including ExponentPart
      { begin: `(\\b(${decimalDigits})((${frac})|\\.)?|(${frac}))` +
        `[eE][+-]?(${decimalDigits})[fFdD]?\\b` },
      // excluding ExponentPart
      { begin: `\\b(${decimalDigits})((${frac})[fFdD]?\\b|\\.([fFdD]\\b)?)` },
      { begin: `(${frac})[fFdD]?\\b` },
      { begin: `\\b(${decimalDigits})[fFdD]\\b` },

      // HexadecimalFloatingPointLiteral
      { begin: `\\b0[xX]((${hexDigits})\\.?|(${hexDigits})?\\.(${hexDigits}))` +
        `[pP][+-]?(${decimalDigits})[fFdD]?\\b` },

      // DecimalIntegerLiteral
      { begin: '\\b(0|[1-9](_*[0-9])*)[lL]?\\b' },

      // HexIntegerLiteral
      { begin: `\\b0[xX](${hexDigits})[lL]?\\b` },

      // OctalIntegerLiteral
      { begin: '\\b0(_*[0-7])*[lL]?\\b' },

      // BinaryIntegerLiteral
      { begin: '\\b0[bB][01](_*[01])*[lL]?\\b' },
    ],
    relevance: 0
  };

  function zig(hljs) {
    //const regex = hljs.regex;

    const LITERALS = [
      "null",
      "undefined",
      "true",
      "false",
    ];

    const TYPES = [
      // Integer
      "f16",
      "f32",
      "f64",
      "f80",
      "f128",
      "usize",
      "isize",
      "comptime_int",
      "comptime_float",

      // Type
      "bool",
      "void",
      "noreturn",
      "type",
      "error",
      "anyerror",
      "anyframe",
      "anytype",
      "anyopaque",

      // C
      "c_short",
      "c_ushort",
      "c_int",
      "c_uint",
      "c_long",
      "c_ulong",
      "c_longlong",
      "c_longdouble"
    ];

    const MAIN_KEYWORDS = [
      "const",
      "let",
      "fn",
      // Repeat
      "inline",
      "while",
      "for",
      // Storage
      "extern",
      "packed",
      "export",
      "pub",
      "noalias",
      "comptime",
      "volatile",
      "align",
      "linksection",
      "threadlocal",
      "allowzero",
      "noinline",
      "callconv",
      // Structure
      "struct",
      "enum",
      "union",
      "opaque",
      // Statement
      "asm",
      "unreachable",
      // Flow
      "break",
      "return",
      "continue",
      "defer",
      "errdefer",
      // Async
      "await",
      "resume",
      "suspend",
      "async",
      "nosuspend",
      // Try Catch
      "try",
      "catch",
      // Conditional
      "if",
      "else",
      "switch",
      "orelse",
      // Default
      "usingnamespace",
      "test",
      "and",
      "or",
    ];

    const KEYWORDS = {
      keyword: MAIN_KEYWORDS,
      literal: LITERALS,
      type: TYPES,
    };

    const ZIG_IDENT_RE = "[_a-zA-Z][_a-zA-Z0-9]*";
    const GENERIC_IDENT_RE = ZIG_IDENT_RE;

    const INT_TYPE = {
      match: /(u|i)\d+/,
      className: "type",
    };

    const MULTILINE_STRING = {
      begin: /\\\\/,
      end: /\n/,
      className: "string"
    };

    const COMMENT = {
      begin: /\/\//,
      end: /\n/,
      className: "comment"
    };

    return {
      name: 'ZIG',
      keywords: KEYWORDS,
      aliases: [ 'zig', ],
      contains: [
        {
          match: "@" + GENERIC_IDENT_RE,
          className: "built_in",
        },
        {
          begin: [
            '(?:' + GENERIC_IDENT_RE + '\\s+)',
            hljs.UNDERSCORE_IDENT_RE,
            /\s*(?=\()/
          ],
          className: { 2: "title.function" },
          keywords: KEYWORDS,
          contains: [
            {
              className: 'params',
              begin: /\(/,
              end: /\)/,
              keywords: KEYWORDS,
              relevance: 0,
              contains: [
                hljs.APOS_STRING_MODE,
                hljs.QUOTE_STRING_MODE,
                hljs.C_BLOCK_COMMENT_MODE,
                INT_TYPE,
              ]
            },
            hljs.C_LINE_COMMENT_MODE,
            hljs.C_BLOCK_COMMENT_MODE
          ]
        },
        {
          // Expression keywords prevent 'keyword Name(...)' from being
          // recognized as a function definition
          beginKeywords: 'struct union enum error',
          relevance: 0
        },
        {
          begin: [
            GENERIC_IDENT_RE,
            /\s*(?=\{)/
          ],
          className: { 1: "title.class" },
          keywords: KEYWORDS,
          contains: [
            hljs.C_LINE_COMMENT_MODE,
            hljs.C_BLOCK_COMMENT_MODE,
            INT_TYPE
          ]
        },
        {
          beginKeywords: "struct",
          relevance: 0
        },
        {
          match: [
            GENERIC_IDENT_RE,
            /\s*:\s*/,
            GENERIC_IDENT_RE
          ],
          className: { 3: "type" }
        },
        hljs.QUOTE_STRING_MODE,
        MULTILINE_STRING,
        NUMBER,
        COMMENT,
        INT_TYPE,
      ],
    };
  }

  hljs.registerLanguage("zig", zig);
})();
